// Golden tests for CreasePattern (default square, duplicate rejection, nearest queries, grid
// snapping, type changes, orphan cleanup, cleanStraightLines, flat-foldability) and for
// HistoryManager undo/redo semantics (new line, deleted line, type change, branches, FixedStack cap).
// Goldens generated by tools/fixtures/core/creasepattern.js from the reference JS implementation.
import Foundation
import ORIPACore

private struct CreasePatternFixture: Decodable {
    struct Defaults: Decodable {
        let halfSize: Double
        let inputLineType: Int
        let modified: Int
        let lineCount: Int
        let pointCount: Int
        let facesCheckCount: Int
        let pointErrorCheckCount: Int
        let minMax: [Double]
        let gridRenderVertexCount: Int
        let hasUndo: Int
        let customHalfSize: Double
        let customInputLineType: Int
        let customMinMax: [Double]
    }

    struct Square: Decodable {
        let lineCount: Int
        let pointCount: Int
        let lines: [[Double]]
        let points: [[Double]]
        let minMax: [Double]
        let findPointCenter: [Double]?
        let findLineEdge: [Double]?
    }

    struct AddReject: Decodable {
        let before: Int
        let countAfterAdd: Int
        let pointCountAfterAdd: Int
        let countAfterDuplicate: Int
        let countAfterDiagonal: Int
        let countAfterDiagonalDuplicate: Int
        let countAfterDegenerate: Int
        let pointCountAfterDegenerate: Int
    }

    struct FindQueries: Decodable {
        let pointNoSnapNearest: [Double]?
        let pointNoSnapMiss: [Double]?
        let pointWithSnap: [Double]?
        let lineNoSnapNearest: [Double]?
        let lineNoSnapMiss: [Double]?
        let lineWithGridNearest: [Double]?
    }

    struct ChangeType: Decodable {
        let typeAfter: Int
        let startCounts: [Int]
        let startPoint: [Double]?
        let errorThrows: Int
    }

    struct RemoveOrphan: Decodable {
        let lineCount: Int
        let pointCount: Int
        let containsOldPoint: Int
        let containsOldEndpoint: Int
        let containsSquareCorner: Int
    }

    struct CleanStraight: Decodable {
        let linesBefore: Int
        let lineCount: Int
        let historyItemCount: Int
        let oldLineCount: Int
        let newLineCount: Int
        let mergedStartX: Double
        let mergedEndX: Double
        let pointCount: Int
        let middleGone: Int
        let hasUndo: Int
    }

    struct FaceInvariants: Decodable {
        let count: Int
        let areas: [Double]
        let pointCounts: [Int]
        let typeCounts: [Int]
        let areaSum: Double
    }

    struct FlatValid: Decodable {
        let flat: Int
        let lines: [[Double]]
        let pointCount: Int
        let pointErrorCount: Int
        let faceInvariants: FaceInvariants
        let centerCounts: [Int]
        let minMax: [Double]
    }

    struct ClearCheck: Decodable {
        let pointErrorCount: Int
        let faceCount: Int
    }

    struct FlatInvalid: Decodable {
        let flat: Int
        let lines: [[Double]]
        let pointCount: Int
        let pointErrorCount: Int
        let errorPointKeys: [[Int]]
        let faceCount: Int
        let clearCheckData: ClearCheck
    }

    struct ClearAll: Decodable {
        let lineCount: Int
        let pointCount: Int
        let faceCount: Int
        let pointErrorCount: Int
        let hasUndo: Int
        let hasRedo: Int
        let lineTreeEmpty: Int
        let pointTreeEmpty: Int
    }

    struct HistoryNewLine: Decodable {
        let afterAdd: Int
        let hasUndoAfterBranch: Int
        let hasRedoAfterBranch: Int
        let afterUndo: Int
        let hasUndoAfterUndo: Int
        let hasRedoAfterUndo: Int
        let pointCountAfterUndo: Int
        let afterRedo: Int
        let exactAfterRedo: Int
        let pointsAfterRedo: Int
    }

    struct HistoryDeleteLine: Decodable {
        let afterDelete: Int
        let afterUndo: Int
        let pointCountAfterUndo: Int
        let exactAfterUndo: Int
        let afterRedo: Int
    }

    struct HistoryTypeChange: Decodable {
        let typeAfterChange: Int
        let typeAfterUndo: Int
        let typeAfterRedo: Int
    }

    struct HistoryBranch: Decodable {
        let redoBeforeNewBranch: Int
        let redoAfterNewBranch: Int
        let hasUndo: Int
        let lineCount: Int
    }

    struct HistoryCap: Decodable {
        let undoCount: Int
        let hasUndoAfterClear: Int
    }

    struct HistoryMerge: Decodable {
        let linesAfterMerge: Int
        let linesAfterUndo: Int
        let linesAfterRedo: Int
    }

    struct History: Decodable {
        let newLine: HistoryNewLine
        let deleteLine: HistoryDeleteLine
        let typeChange: HistoryTypeChange
        let branchClearsRedo: HistoryBranch
        let cap: HistoryCap
        let merge: HistoryMerge
    }

    let defaults: Defaults
    let square: Square
    let addReject: AddReject
    let findQueries: FindQueries
    let changeType: ChangeType
    let removeOrphan: RemoveOrphan
    let cleanStraight: CleanStraight
    let flatValid: FlatValid
    let flatInvalid: FlatInvalid
    let clearAll: ClearAll
    let history: History
}

private func line(_ values: [Double]) -> OriLine { CoreModelJSON.line(values) }

private func option(_ point: OriPoint?) -> [Double]? {
    guard let point else { return nil }
    return [point.x, point.y]
}

private func option(_ line: OriLine?) -> [Double]? {
    guard let line else { return nil }
    return CoreModelJSON.lineValues(line)
}

private func sortedPoints(_ creasePattern: CreasePattern) -> [[Double]] {
    creasePattern.points.map { [Double($0.xKey), Double($0.yKey), $0.x, $0.y] }.sorted { lhs, rhs in
        if lhs[0] != rhs[0] { return lhs[0] < rhs[0] }
        return lhs[1] < rhs[1]
    }
}

private func errorKeys(_ creasePattern: CreasePattern) -> [[Int]] {
    creasePattern.pointErrorCheck.map { [$0.xKey, $0.yKey] }.sorted { lhs, rhs in
        if lhs[0] != rhs[0] { return lhs[0] < rhs[0] }
        return lhs[1] < rhs[1]
    }
}

private func faceInvariants(_ creasePattern: CreasePattern) -> CreasePatternFixture.FaceInvariants {
    let faces = creasePattern.facesCheck
    let areas = faces.map { $0.getArea() }.sorted()
    let pointCounts = faces.map { $0.points.count }.sorted()
    let typeCounts = faces.map { $0.lineTypes.count }.sorted()
    return CreasePatternFixture.FaceInvariants(
        count: faces.count,
        areas: areas,
        pointCounts: pointCounts,
        typeCounts: typeCounts,
        areaSum: areas.reduce(0.0, +)
    )
}

private func pointInRange(_ creasePattern: CreasePattern, _ x: Double, _ y: Double) -> OriPoint? {
    let points = creasePattern.pointMVFB.findAllPointsInRange(
        PointDouble(x - 1, y - 1), PointDouble(x + 1, y + 1)
    ).values()
    return points.first
}

enum CreasePatternTests {
    static var all: [TestSuite] {
        [TestSuite("CoreModel.CreasePattern") { harness in
            let fixture = try Fixtures.decode(CreasePatternFixture.self, "Fixtures/core/creasepattern.json")

            // MARK: constructor defaults
            let defaults = fixture.defaults
            let cp = CreasePattern()
            harness.expectEqual(Double(cp.creasePatternHalfSize), defaults.halfSize, "half size")
            harness.expectEqual(cp.inputLineType.rawValue, defaults.inputLineType, "input line type")
            harness.expectEqual(boolValue(cp.modified), defaults.modified, "modified")
            harness.expectEqual(cp.lineMVFB.size(), defaults.lineCount, "line count")
            harness.expectEqual(cp.pointMVFB.size(), defaults.pointCount, "point count")
            harness.expectEqual(cp.facesCheck.count, defaults.facesCheckCount, "facesCheck count")
            harness.expectEqual(cp.pointErrorCheck.count, defaults.pointErrorCheckCount, "pointErrorCheck count")
            expectCloseArray(harness, cp.minMaxCheck.toArray(), defaults.minMax, "minMax")
            harness.expectEqual(cp.grid.getRenderData().vertexPosition.count,
                                defaults.gridRenderVertexCount, "grid render vertex count")
            harness.expectEqual(boolValue(cp.historyManager.hasUndo()), defaults.hasUndo, "history empty")
            let custom = CreasePattern(50, 3)
            harness.expectEqual(Double(custom.creasePatternHalfSize), defaults.customHalfSize, "custom half size")
            harness.expectEqual(custom.inputLineType.rawValue, defaults.customInputLineType, "custom input type")
            expectCloseArray(harness, custom.minMaxCheck.toArray(), defaults.customMinMax, "custom minMax")

            // MARK: initializeDefaultSquare
            let squareCP = CreasePattern()
            squareCP.initializeDefaultSquare()
            harness.expectEqual(squareCP.lineMVFB.size(), fixture.square.lineCount, "square line count")
            harness.expectEqual(squareCP.pointMVFB.size(), fixture.square.pointCount, "square point count")
            expectEqualArray(harness, CoreModelJSON.sortedLineValues(squareCP.lines), fixture.square.lines,
                             "square lines")
            expectEqualArray(harness, sortedPoints(squareCP), fixture.square.points, "square points")
            expectCloseArray(harness, squareCP.minMaxCheck.toArray(), fixture.square.minMax, "square minMax")
            harness.expectEqual(option(squareCP.findPoint(false, PointDouble(0, 0), 300)),
                                fixture.square.findPointCenter, "square findPoint center")
            harness.expectEqual(option(squareCP.findLine(false, PointDouble(250, 0), 100)),
                                fixture.square.findLineEdge, "square findLine edge")

            // MARK: add / duplicate / diagonal duplicate / degenerate rejection
            let addCP = CreasePattern()
            addCP.initializeDefaultSquare()
            harness.expectEqual(addCP.lineMVFB.size(), fixture.addReject.before, "addReject before")
            addCP.addLineCheckNoException(line([0, 0, 100, 0, 2]))
            harness.expectEqual(addCP.lineMVFB.size(), fixture.addReject.countAfterAdd, "addReject after add")
            harness.expectEqual(addCP.pointMVFB.size(), fixture.addReject.pointCountAfterAdd,
                                "addReject point count")
            addCP.addLineCheckNoException(line([100, 0, 0, 0, 3]))
            harness.expectEqual(addCP.lineMVFB.size(), fixture.addReject.countAfterDuplicate,
                                "addReject after duplicate")
            addCP.addLineCheckNoException(line([0, 0, 100, 100, 2]))
            harness.expectEqual(addCP.lineMVFB.size(), fixture.addReject.countAfterDiagonal,
                                "addReject after diagonal")
            addCP.addLineCheckNoException(line([0, 100, 100, 0, 2]))
            harness.expectEqual(addCP.lineMVFB.size(), fixture.addReject.countAfterDiagonalDuplicate,
                                "addReject after diagonal duplicate")
            addCP.addLineCheckNoException(line([5, 5, 5, 5, 2]))
            harness.expectEqual(addCP.lineMVFB.size(), fixture.addReject.countAfterDegenerate,
                                "addReject after degenerate")
            harness.expectEqual(addCP.pointMVFB.size(), fixture.addReject.pointCountAfterDegenerate,
                                "addReject point count after degenerate")

            // MARK: nearest point/line queries (with/without grid snapping)
            let queryCP = CreasePattern()
            queryCP.initializeDefaultSquare()
            queryCP.addLineCheckNoException(line([0, 0, 100, 0, 2]))
            let queries = fixture.findQueries
            harness.expectEqual(option(queryCP.findPoint(false, PointDouble(3, 3), 10)),
                                queries.pointNoSnapNearest, "findPoint nearest")
            harness.expectEqual(option(queryCP.findPoint(false, PointDouble(3, 3), 2)),
                                queries.pointNoSnapMiss, "findPoint miss")
            harness.expectEqual(option(queryCP.findPoint(true, PointDouble(3, 3), 10)),
                                queries.pointWithSnap, "findPoint with grid")
            harness.expectEqual(option(queryCP.findLine(false, PointDouble(50, 2), 10)),
                                queries.lineNoSnapNearest, "findLine nearest")
            harness.expectEqual(option(queryCP.findLine(false, PointDouble(50, 50), 3)),
                                queries.lineNoSnapMiss, "findLine miss")
            harness.expectEqual(option(queryCP.findLine(true, PointDouble(99, 2), 5)),
                                queries.lineWithGridNearest, "findLine with grid")

            // MARK: changeLineType (+ error path)
            let changeCP = CreasePattern()
            changeCP.addLineCheckNoException(line([0, 0, 100, 0, 2]))
            let stored = changeCP.lineMVFB.findExact(line([0, 0, 100, 0, 2]))
            harness.expectNotNil(stored, "changeLineType findExact")
            if let stored {
                changeCP.changeLineType(stored, .valley)
                harness.expectEqual(stored.typeValue, fixture.changeType.typeAfter, "changeLineType type")
                if let start = pointInRange(changeCP, 0, 0) {
                    let counts = [0, 1, 2, 3].map { start.getLineTypeCount($0) }
                    expectEqualArray(harness, counts, fixture.changeType.startCounts, "changeLineType counts")
                    harness.expectEqual([start.x, start.y], fixture.changeType.startPoint, "changeLineType point")
                } else {
                    harness.fail("changeLineType start point missing")
                }
            }
            harness.expectEqual(
                boolValue(doesThrow { try changeCP.changeLineTypeChecked(line([0, 0, 50, 0, 2]), .valley) }),
                fixture.changeType.errorThrows, "changeLineType unknown line throws"
            )

            // MARK: removeLine removes orphan points
            let removeCP = CreasePattern()
            removeCP.initializeDefaultSquare()
            removeCP.addLineCheckNoException(line([0, 0, 100, 0, 2]))
            if let added = removeCP.lineMVFB.findExact(line([0, 0, 100, 0, 2])) {
                removeCP.removeLine(added)
            }
            harness.expectEqual(removeCP.lineMVFB.size(), fixture.removeOrphan.lineCount, "removeOrphan line count")
            harness.expectEqual(removeCP.pointMVFB.size(), fixture.removeOrphan.pointCount,
                                "removeOrphan point count")
            harness.expectEqual(boolValue(removeCP.pointMVFB.contains(OriPoint(0, 0))),
                                fixture.removeOrphan.containsOldPoint, "removeOrphan old point")
            harness.expectEqual(boolValue(removeCP.pointMVFB.contains(OriPoint(100, 0))),
                                fixture.removeOrphan.containsOldEndpoint, "removeOrphan old endpoint")
            harness.expectEqual(boolValue(removeCP.pointMVFB.contains(OriPoint(200, 200))),
                                fixture.removeOrphan.containsSquareCorner, "removeOrphan square corner")

            // MARK: cleanStraightLines
            let cleanCP = CreasePattern()
            cleanCP.addLineCheckNoException(line([0, 0, 50, 0, 2]))
            cleanCP.addLineCheckNoException(line([50, 0, 100, 0, 2]))
            harness.expectEqual(cleanCP.lineMVFB.size(), fixture.cleanStraight.linesBefore, "clean lines before")
            if let middle = pointInRange(cleanCP, 50, 0) {
                let points = JavaSet<OriPoint>()
                points.add(middle)
                let historyItems = cleanCP.cleanStraightLines(points)
                harness.expectEqual(cleanCP.lineMVFB.size(), fixture.cleanStraight.lineCount, "clean line count")
                harness.expectEqual(historyItems.count, fixture.cleanStraight.historyItemCount,
                                    "clean history item count")
                if let item = historyItems.first {
                    harness.expectEqual(item.oldLines.count, fixture.cleanStraight.oldLineCount,
                                        "clean old lines")
                    harness.expectEqual(item.newLines.count, fixture.cleanStraight.newLineCount,
                                        "clean new lines")
                }
            } else {
                harness.fail("cleanStraight middle point missing")
            }
            harness.expectEqual(cleanCP.pointMVFB.size(), fixture.cleanStraight.pointCount, "clean point count")
            // fixture stores `contains ? 0 : 1` (JS generator), so invert back for the assertion
            harness.expectEqual(boolValue(cleanCP.pointMVFB.contains(OriPoint(50, 0))),
                                1 - fixture.cleanStraight.middleGone, "clean middle gone")
            if let merged = cleanCP.lineMVFB.getAllLines().first {
                harness.expectClose(min(merged.start.x, merged.end.x),
                                    fixture.cleanStraight.mergedStartX, "clean merged start")
                harness.expectClose(max(merged.start.x, merged.end.x),
                                    fixture.cleanStraight.mergedEndX, "clean merged end")
            }
            harness.expectEqual(boolValue(cleanCP.historyManager.hasUndo()), fixture.cleanStraight.hasUndo,
                                "clean does not branch history")

            // MARK: isFlatFoldable (valid 4-crease interior vertex)
            let validCP = CoreModelJSON.buildCreasePattern(fromLines: fixture.flatValid.lines)
            harness.expectEqual(validCP.pointMVFB.size(), fixture.flatValid.pointCount, "flat valid point count")
            let validFlat = validCP.isFlatFoldable()
            harness.expectEqual(boolValue(validFlat), fixture.flatValid.flat, "flat valid result")
            harness.expectEqual(validCP.pointErrorCheck.count, fixture.flatValid.pointErrorCount,
                                "flat valid point errors")
            let validFaces = faceInvariants(validCP)
            harness.expectEqual(validFaces.count, fixture.flatValid.faceInvariants.count, "flat valid faces")
            expectCloseArray(harness, validFaces.areas, fixture.flatValid.faceInvariants.areas, accuracy: 1e-9,
                             "flat valid areas")
            expectEqualArray(harness, validFaces.pointCounts, fixture.flatValid.faceInvariants.pointCounts,
                             "flat valid face point counts")
            expectEqualArray(harness, validFaces.typeCounts, fixture.flatValid.faceInvariants.typeCounts,
                             "flat valid face type counts")
            harness.expectClose(validFaces.areaSum, fixture.flatValid.faceInvariants.areaSum, accuracy: 1e-9,
                                "flat valid area sum")
            if let center = pointInRange(validCP, 0, 0) {
                let counts = [0, 1, 2, 3].map { center.getLineTypeCount($0) }
                expectEqualArray(harness, counts, fixture.flatValid.centerCounts, "flat valid center counts")
            } else {
                harness.fail("flat valid center missing")
            }
            expectCloseArray(harness, validCP.minMaxCheck.toArray(), fixture.flatValid.minMax,
                             "flat valid minMax")

            // MARK: isFlatFoldable (Maekawa violation detected)
            let invalidCP = CoreModelJSON.buildCreasePattern(fromLines: fixture.flatInvalid.lines)
            harness.expectEqual(invalidCP.pointMVFB.size(), fixture.flatInvalid.pointCount,
                                "flat invalid point count")
            let invalidFlat = invalidCP.isFlatFoldable()
            harness.expectEqual(boolValue(invalidFlat), fixture.flatInvalid.flat, "flat invalid result")
            harness.expectEqual(invalidCP.pointErrorCheck.count, fixture.flatInvalid.pointErrorCount,
                                "flat invalid point errors")
            harness.expectEqual(errorKeys(invalidCP), fixture.flatInvalid.errorPointKeys,
                                "flat invalid error points")
            harness.expectEqual(invalidCP.facesCheck.count, fixture.flatInvalid.faceCount,
                                "flat invalid face count")
            invalidCP.clearCheckData()
            harness.expectEqual(invalidCP.pointErrorCheck.count,
                                fixture.flatInvalid.clearCheckData.pointErrorCount, "clearCheckData point errors")
            harness.expectEqual(invalidCP.facesCheck.count, fixture.flatInvalid.clearCheckData.faceCount,
                                "clearCheckData faces")

            // MARK: clearAll
            let clearCP = CoreModelJSON.buildCreasePattern(fromLines: fixture.flatValid.lines)
            clearCP.modified = true
            _ = clearCP.isFlatFoldable()
            clearCP.clearAll()
            harness.expectEqual(clearCP.lineMVFB.size(), fixture.clearAll.lineCount, "clearAll line count")
            harness.expectEqual(clearCP.pointMVFB.size(), fixture.clearAll.pointCount, "clearAll point count")
            harness.expectEqual(clearCP.facesCheck.count, fixture.clearAll.faceCount, "clearAll faces")
            harness.expectEqual(clearCP.pointErrorCheck.count, fixture.clearAll.pointErrorCount,
                                "clearAll point errors")
            harness.expectEqual(boolValue(clearCP.historyManager.hasUndo()), fixture.clearAll.hasUndo,
                                "clearAll hasUndo")
            harness.expectEqual(boolValue(clearCP.historyManager.hasRedo()), fixture.clearAll.hasRedo,
                                "clearAll hasRedo")
            harness.expectEqual(boolValue(clearCP.lineMVFB.isEmpty()), fixture.clearAll.lineTreeEmpty,
                                "clearAll line tree empty")
            harness.expectEqual(boolValue(clearCP.pointMVFB.isEmpty()), fixture.clearAll.pointTreeEmpty,
                                "clearAll point tree empty")

            // MARK: history — undo/redo new line
            let newLineFixture = fixture.history.newLine
            let historyCP = CreasePattern()
            historyCP.addLineCheckNoException(line([0, 0, 100, 0, 2]))
            historyCP.addLineCheckNoException(line([0, 100, 100, 100, 2]))
            let addedLine = line([0, 0, 0, 100, 3])
            historyCP.addLineNoCheck(addedLine)
            let newItem = HistoryItem()
            newItem.newLines.append(addedLine)
            let newGroup = HistoryGroup(0)
            newGroup.add(newItem)
            historyCP.historyManager.newBranch(newGroup)
            harness.expectEqual(historyCP.lineMVFB.size(), newLineFixture.afterAdd, "history new line after add")
            harness.expectEqual(boolValue(historyCP.historyManager.hasUndo()),
                                newLineFixture.hasUndoAfterBranch, "history hasUndo after branch")
            harness.expectEqual(boolValue(historyCP.historyManager.hasRedo()),
                                newLineFixture.hasRedoAfterBranch, "history hasRedo after branch")
            historyCP.historyManager.undo(historyCP)
            harness.expectEqual(historyCP.lineMVFB.size(), newLineFixture.afterUndo, "history new line after undo")
            harness.expectEqual(boolValue(historyCP.historyManager.hasUndo()),
                                newLineFixture.hasUndoAfterUndo, "history hasUndo after undo")
            harness.expectEqual(boolValue(historyCP.historyManager.hasRedo()),
                                newLineFixture.hasRedoAfterUndo, "history hasRedo after undo")
            harness.expectEqual(historyCP.pointMVFB.size(), newLineFixture.pointCountAfterUndo,
                                "history new line points after undo")
            historyCP.historyManager.redo(historyCP)
            harness.expectEqual(historyCP.lineMVFB.size(), newLineFixture.afterRedo, "history new line after redo")
            harness.expectEqual(boolValue(historyCP.lineMVFB.findExact(line([0, 0, 0, 100, 3])) != nil),
                                newLineFixture.exactAfterRedo, "history redo exact line")
            harness.expectEqual(historyCP.pointMVFB.size(), newLineFixture.pointsAfterRedo,
                                "history new line points after redo")

            // MARK: history — undo/redo delete line
            let deleteFixture = fixture.history.deleteLine
            let deleteCP = CreasePattern()
            deleteCP.addLineCheckNoException(line([0, 0, 100, 0, 2]))
            if let stored = deleteCP.lineMVFB.findExact(line([0, 0, 100, 0, 2])) {
                let deleteItem = HistoryItem()
                deleteItem.oldLines.append(stored)
                deleteCP.removeLine(stored)
                let deleteGroup = HistoryGroup(0)
                deleteGroup.add(deleteItem)
                deleteCP.historyManager.newBranch(deleteGroup)
            }
            harness.expectEqual(deleteCP.lineMVFB.size(), deleteFixture.afterDelete, "history delete after delete")
            deleteCP.historyManager.undo(deleteCP)
            harness.expectEqual(deleteCP.lineMVFB.size(), deleteFixture.afterUndo, "history delete after undo")
            harness.expectEqual(deleteCP.pointMVFB.size(), deleteFixture.pointCountAfterUndo,
                                "history delete points after undo")
            harness.expectEqual(boolValue(deleteCP.lineMVFB.findExact(line([0, 0, 100, 0, 2])) != nil),
                                deleteFixture.exactAfterUndo, "history delete exact line after undo")
            deleteCP.historyManager.redo(deleteCP)
            harness.expectEqual(deleteCP.lineMVFB.size(), deleteFixture.afterRedo, "history delete after redo")

            // MARK: history — undo/redo line type change
            let typeFixture = fixture.history.typeChange
            let typeCP = CreasePattern()
            typeCP.addLineCheckNoException(line([0, 0, 100, 0, 2]))
            if let stored = typeCP.lineMVFB.findExact(line([0, 0, 100, 0, 2])) {
                let change = HistoryTypeChange(stored, .mountain, .valley)
                let typeItem = HistoryItem()
                typeItem.changeLines.append(change)
                typeCP.changeLineType(stored, .valley)
                let typeGroup = HistoryGroup(0)
                typeGroup.add(typeItem)
                typeCP.historyManager.newBranch(typeGroup)
                harness.expectEqual(stored.typeValue, typeFixture.typeAfterChange, "history type after change")
                typeCP.historyManager.undo(typeCP)
                harness.expectEqual(stored.typeValue, typeFixture.typeAfterUndo, "history type after undo")
                typeCP.historyManager.redo(typeCP)
                harness.expectEqual(stored.typeValue, typeFixture.typeAfterRedo, "history type after redo")
            } else {
                harness.fail("history type change line missing")
            }

            // MARK: history — new branch clears redo
            let branchFixture = fixture.history.branchClearsRedo
            let branchCP = CreasePattern()
            branchCP.addLineCheckNoException(line([0, 0, 100, 0, 2]))
            branchCP.addLineCheckNoException(line([0, 100, 100, 100, 2]))
            func branchWithNewLine(_ x: Double) {
                let added = line([x, 0, x, 100, 3])
                branchCP.addLineNoCheck(added)
                let item = HistoryItem()
                item.newLines.append(added)
                let group = HistoryGroup(0)
                group.add(item)
                branchCP.historyManager.newBranch(group)
            }
            branchWithNewLine(0)
            branchCP.historyManager.undo(branchCP)
            harness.expectEqual(boolValue(branchCP.historyManager.hasRedo()),
                                branchFixture.redoBeforeNewBranch, "history redo before new branch")
            branchWithNewLine(50)
            harness.expectEqual(boolValue(branchCP.historyManager.hasRedo()),
                                branchFixture.redoAfterNewBranch, "history redo cleared by new branch")
            harness.expectEqual(boolValue(branchCP.historyManager.hasUndo()), branchFixture.hasUndo,
                                "history hasUndo after branch")
            harness.expectEqual(branchCP.lineMVFB.size(), branchFixture.lineCount, "history branch line count")

            // MARK: history — FixedStack(50) cap
            let capFixture = fixture.history.cap
            let capCP = CreasePattern()
            capCP.addLineCheckNoException(line([0, 0, 100, 0, 2]))
            for _ in 0..<60 {
                capCP.historyManager.newBranch(HistoryGroup(0))
            }
            var undoCount = 0
            while capCP.historyManager.hasUndo() {
                capCP.historyManager.undo(capCP)
                undoCount += 1
                if undoCount > 100 { break }
            }
            harness.expectEqual(undoCount, capFixture.undoCount, "history fixed stack cap")
            capCP.historyManager.clearAll()
            harness.expectEqual(boolValue(capCP.historyManager.hasUndo()), capFixture.hasUndoAfterClear,
                                "history clearAll")

            // MARK: history — undo/redo cleanStraightLines merge
            let mergeFixture = fixture.history.merge
            let mergeCP = CreasePattern()
            mergeCP.addLineCheckNoException(line([0, 0, 50, 0, 2]))
            mergeCP.addLineCheckNoException(line([50, 0, 100, 0, 2]))
            if let middle = pointInRange(mergeCP, 50, 0) {
                let set = JavaSet<OriPoint>()
                set.add(middle)
                let items = mergeCP.cleanStraightLines(set)
                let group = HistoryGroup(0)
                group.addAll(items)
                harness.expectEqual(mergeCP.lineMVFB.size(), mergeFixture.linesAfterMerge,
                                    "history merge lines after merge")
                mergeCP.historyManager.newBranch(group)
                mergeCP.historyManager.undo(mergeCP)
                harness.expectEqual(mergeCP.lineMVFB.size(), mergeFixture.linesAfterUndo,
                                    "history merge lines after undo")
                mergeCP.historyManager.redo(mergeCP)
                harness.expectEqual(mergeCP.lineMVFB.size(), mergeFixture.linesAfterRedo,
                                    "history merge lines after redo")
            } else {
                harness.fail("history merge middle point missing")
            }
        }]
    }
}
